from collections import Counter, defaultdict


def transform(grid):
    """Extend the input's colored diagonal pattern periodically."""
    h, w = len(grid), len(grid[0])

    # The given diagonal strokes can run in either diagonal direction.
    grouped = {}
    scores = {}
    for axis in ("sum", "diff"):
        lines = defaultdict(list)
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value:
                    key = r + c if axis == "sum" else c - r
                    lines[key].append(value)
        grouped[axis] = lines
        scores[axis] = sum(max(Counter(values).values()) for values in lines.values())

    axis = "sum" if scores["sum"] >= scores["diff"] else "diff"
    samples = {}
    for key, values in grouped[axis].items():
        samples[key] = Counter(values).most_common(1)[0][0]

    # The motif is the shortest period that gives each sampled stripe one color.
    period = None
    pattern = None
    for candidate in range(1, 2 * (h + w) + 1):
        trial = {}
        consistent = True
        for key, color in samples.items():
            residue = key % candidate
            if residue in trial and trial[residue] != color:
                consistent = False
                break
            trial[residue] = color
        if consistent:
            period, pattern = candidate, trial
            break

    if period is None:  # Defensive fallback; a period larger than the grid span fits.
        period = 2 * (h + w) + 1
        pattern = {key % period: color for key, color in samples.items()}

    result = []
    for r in range(h):
        row = []
        for c in range(w):
            key = r + c if axis == "sum" else c - r
            row.append(pattern.get(key % period, 0))
        result.append(row)
    return result

